import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Portal","description":"","frontmatter":{"title":"Portal"},"headers":[],"relativePath":"de/api/reference/portal.md","filePath":"de/api/reference/portal.md"}`),a={name:`de/api/reference/portal.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="portal" tabindex="-1">Portal <a class="header-anchor" href="#portal" aria-label="Permalink to “Portal”">​</a></h1><div><p>Operationen des Tags <strong>Portal</strong>, die dieses Release implementiert. Erzeugt aus <code>api/openapi.yaml</code>; geplante Operationen sind nicht aufgeführt. Die Beschreibungen stammen aus dem englischen API-Vertrag.</p><h2 id="listPortalCatalogs" tabindex="-1">Shared catalogs of the portal (SCR-050) <a class="header-anchor" href="#listPortalCatalogs" aria-label="Permalink to “Shared catalogs of the portal (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs</code> · <code>listPortalCatalogs</code></p><p>The catalogs with scope <code>instance</code>, ordered by name (case-insensitive). Personal catalogs never appear in the portal, not even the caller&#39;s own.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="antworten" tabindex="-1">Antworten <a class="header-anchor" href="#antworten" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Shared catalogs</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="queryPortalCatalog" tabindex="-1">Query a shared catalog read-only (SCR-050) <a class="header-anchor" href="#queryPortalCatalog" aria-label="Permalink to “Query a shared catalog read-only (SCR-050)”">​</a></h2><p><code>GET /portal/catalogs/{id}/query</code> · <code>queryPortalCatalog</code></p><p>One page of rows of a catalog with scope <code>instance</code>, with the catalog&#39;s configured columns, default sort and default join mode. The result equals that of the catalog query (<code>queryCatalog</code>) without filters, join mode overrides or view, including its visibility rules (<code>CatalogColumn.readable</code>, REQ-124, REQ-160), the override role list and its <code>property-override-access</code> audit event (REQ-128), and soft-deleted entities are not returned. <code>page</code>, <code>pageSize</code>, <code>sort</code>, <code>cursor</code> and the query time limit (503 <code>query-timeout</code>) behave as in the catalog query. A personal catalog is answered with 404, like a catalog that does not exist, also for its creator.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>page</code></td><td>query</td><td>nein</td><td>integer</td><td>–</td></tr><tr><td><code>pageSize</code></td><td>query</td><td>nein</td><td>integer</td><td>–</td></tr><tr><td><code>sort</code></td><td>query</td><td>nein</td><td>string</td><td><code>{field}:{asc|desc}</code>, multiple comma-separated</td></tr><tr><td><code>cursor</code></td><td>query</td><td>nein</td><td>string</td><td>The <code>nextCursor</code> of the previous page, sent together with <code>page</code> set to that page&#39;s number + 1 (REQ-071). The page then starts after the last row of the previous one instead of skipping rows. The cursor is valid only for the same query (catalog, columns or view, sort, join modes, filters, page size) and only until the backend restarts or the catalog changes; otherwise the query is answered with 400 <code>cursor</code> and the client repeats it without the cursor.</td></tr></tbody></table><h3 id="antworten-1" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-1" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>One page of catalog rows</td><td>–</td></tr><tr><td>400</td><td>Invalid paging, sort or cursor parameters (problem type <code>urn:oea:problem:validation-failed</code>), e.g. an unknown sort column, a sort on a column the reader may not read, a page size above 200 or a cursor of another query; <code>invalidFields</code> names the rejected parameters.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr><tr><td>503</td><td>The query took longer than the configured time limit (<code>oea.catalog.query-timeout</code>, 10 seconds by default) and was cancelled (problem type <code>urn:oea:problem:query-timeout</code>, REQ-186, REQ-071). Nothing was changed; narrowing the filters or the joins makes the query cheaper.</td><td><code>urn:oea:problem:query-timeout</code></td></tr></tbody></table><h2 id="listPortalDashboards" tabindex="-1">Dashboards of the portal (SCR-050, US-061) <a class="header-anchor" href="#listPortalDashboards" aria-label="Permalink to “Dashboards of the portal (SCR-050, US-061)”">​</a></h2><p><code>GET /portal/dashboards</code> · <code>listPortalDashboards</code></p><p>The dashboards with scope <code>instance</code> and the caller&#39;s own personal dashboards, ordered by name (case-insensitive), each with <code>canEdit: false</code>. Personal dashboards of other persons never appear, also not for holders of <code>settings:manage</code>. Service accounts get 403.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="antworten-2" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-2" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Visible dashboards</td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="getPortalDashboard" tabindex="-1">Portal dashboard configuration (SCR-053, US-061, US-060) <a class="header-anchor" href="#getPortalDashboard" aria-label="Permalink to “Portal dashboard configuration (SCR-053, US-061, US-060)”">​</a></h2><p><code>GET /portal/dashboards/{id}</code> · <code>getPortalDashboard</code></p><p>The dashboard with its widgets, their types, titles, settings and grid positions, always with <code>canEdit: false</code>. The <code>version</code> carries no write meaning in the portal and there is no <code>ETag</code>. A shared dashboard and the caller&#39;s own personal dashboard are readable; another person&#39;s personal dashboard is answered with 404, like an unknown dashboard, also for holders of <code>settings:manage</code>. Service accounts get 403, also for an unknown ID.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="parameter-1" tabindex="-1">Parameter <a class="header-anchor" href="#parameter-1" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr></tbody></table><h3 id="antworten-3" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-3" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Dashboard configuration</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="getPortalDashboardData" tabindex="-1">Portal dashboard data (SCR-053, US-061) <a class="header-anchor" href="#getPortalDashboardData" aria-label="Permalink to “Portal dashboard data (SCR-053, US-061)”">​</a></h2><p><code>GET /portal/dashboards/{id}/data</code> · <code>getPortalDashboardData</code></p><p>The data of all widgets, computed on each request with the reader&#39;s permissions and property visibility, as <code>getDashboardData</code>. A table widget gives its first page and is measured with the metrics channel <code>portal</code>. A widget that fails gets <code>status: error</code> and the others are computed normally. Visibility of the dashboard and service accounts as <code>getPortalDashboard</code>. A table widget whose catalog query exceeds the time limit fails the request with 503 <code>query-timeout</code>.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="parameter-2" tabindex="-1">Parameter <a class="header-anchor" href="#parameter-2" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr></tbody></table><h3 id="antworten-4" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-4" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Widget data</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr><tr><td>503</td><td>The query took longer than the configured time limit (<code>oea.catalog.query-timeout</code>, 10 seconds by default) and was cancelled (problem type <code>urn:oea:problem:query-timeout</code>, REQ-186, REQ-071). Nothing was changed; narrowing the filters or the joins makes the query cheaper.</td><td><code>urn:oea:problem:query-timeout</code></td></tr></tbody></table><h2 id="getPortalDashboardWidgetData" tabindex="-1">Portal data of one dashboard widget (SCR-053, US-061) <a class="header-anchor" href="#getPortalDashboardWidgetData" aria-label="Permalink to “Portal data of one dashboard widget (SCR-053, US-061)”">​</a></h2><p><code>GET /portal/dashboards/{id}/widgets/{widgetId}/data</code> · <code>getPortalDashboardWidgetData</code></p><p>The data of one widget, for further pages of a table widget. <code>page</code> is 0-based as in <code>queryPortalCatalog</code>; the page size is that of the widget. Visibility, service accounts and the time limit as <code>getPortalDashboardData</code>; an unknown widget is answered with 404.</p><p><strong>Zugriff</strong>: Berechtigung <code>portal:read</code></p><h3 id="parameter-3" tabindex="-1">Parameter <a class="header-anchor" href="#parameter-3" aria-label="Permalink to “Parameter”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Ort</th><th>Pflicht</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>widgetId</code></td><td>path</td><td>ja</td><td>string (uuid)</td><td>–</td></tr><tr><td><code>page</code></td><td>query</td><td>nein</td><td>integer</td><td>–</td></tr></tbody></table><h3 id="antworten-5" tabindex="-1">Antworten <a class="header-anchor" href="#antworten-5" aria-label="Permalink to “Antworten”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Beschreibung</th><th>Problem-Typen</th></tr></thead><tbody><tr><td>200</td><td>Widget data</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code>, <code>POST /me/password/suggestion</code> and <code>GET /me/password/rules</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Resource not found, or an existence-sensitive resource the caller may not see (same response for both cases, REQ-159)</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr><tr><td>503</td><td>The query took longer than the configured time limit (<code>oea.catalog.query-timeout</code>, 10 seconds by default) and was cancelled (problem type <code>urn:oea:problem:query-timeout</code>, REQ-186, REQ-071). Nothing was changed; narrowing the filters or the joins makes the query cheaper.</td><td><code>urn:oea:problem:query-timeout</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};